-- Advisory invitation timestamps are outside immutable create/settlement receipts.
-- Legacy absence stays absent. An appended first observation cannot be changed
-- or removed, including by equal-head projection retries. Exact subsecond UTC
-- comparison avoids rounding away contradictory source evidence.
CREATE TRIGGER invitation_timing_insert BEFORE INSERT ON delivery_outcomes
WHEN (json_extract(NEW.receipt,'$.invitation_timing') IS NOT NULL AND (
 json_type(NEW.receipt,'$.invitation_timing') IS NOT 'object'
 OR json_type(NEW.receipt,'$.invitation_timing.upstream_id') IS NOT 'integer'
 OR json_extract(NEW.receipt,'$.invitation_timing.upstream_id') NOT BETWEEN 1 AND 9007199254740991
 OR json_extract(NEW.receipt,'$.invitation_timing.upstream_id') IS NOT json_extract(NEW.receipt,'$.create.outcome.upstream_id')
 OR json_extract(NEW.receipt,'$.create.outcome.kind') NOT IN ('created','already_pending')
 OR NOT (json_extract(NEW.receipt,'$.invitation_timing.created_at') IS NOT NULL AND julianday(json_extract(NEW.receipt,'$.invitation_timing.created_at')) IS NOT NULL AND substr(replace(json_extract(NEW.receipt,'$.invitation_timing.created_at'),'+00:00','Z'),-1)='Z' AND (length(replace(json_extract(NEW.receipt,'$.invitation_timing.created_at'),'+00:00','Z'))=20 OR (length(replace(json_extract(NEW.receipt,'$.invitation_timing.created_at'),'+00:00','Z')) BETWEEN 22 AND 30 AND substr(replace(json_extract(NEW.receipt,'$.invitation_timing.created_at'),'+00:00','Z'),20,1)='.' AND substr(replace(json_extract(NEW.receipt,'$.invitation_timing.created_at'),'+00:00','Z'),21,length(replace(json_extract(NEW.receipt,'$.invitation_timing.created_at'),'+00:00','Z'))-21) NOT GLOB '*[^0-9]*')))
 OR NOT (json_extract(NEW.receipt,'$.invitation_timing.observed_at') IS NOT NULL AND julianday(json_extract(NEW.receipt,'$.invitation_timing.observed_at')) IS NOT NULL AND substr(replace(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),'+00:00','Z'),-1)='Z' AND (length(replace(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),'+00:00','Z'))=20 OR (length(replace(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),'+00:00','Z')) BETWEEN 22 AND 30 AND substr(replace(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),'+00:00','Z'),20,1)='.' AND substr(replace(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),'+00:00','Z'),21,length(replace(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),'+00:00','Z'))-21) NOT GLOB '*[^0-9]*')))
 OR (substr(json_extract(NEW.receipt,'$.invitation_timing.created_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.invitation_timing.created_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.invitation_timing.created_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) > (substr(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9))
 OR (substr(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.invitation_timing.observed_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) < (substr(json_extract(NEW.receipt,'$.create.command.approved_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.create.command.approved_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.create.command.approved_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9))
 OR (json_extract(NEW.receipt,'$.create.outcome.kind')='created'
     AND substr(json_extract(NEW.receipt,'$.invitation_timing.created_at'),1,19) < substr(json_extract(NEW.receipt,'$.create.command.approved_at'),1,19))
 OR (json_extract(NEW.receipt,'$.invitation_timing.owned_lifetime_seconds') IS NOT NULL AND (json_type(NEW.receipt,'$.invitation_timing.owned_lifetime_seconds') IS NOT 'integer' OR json_extract(NEW.receipt,'$.invitation_timing.owned_lifetime_seconds') NOT BETWEEN 3600 AND 604800))
 OR (json_extract(NEW.receipt,'$.create.outcome.created_at') IS NOT NULL AND (substr(json_extract(NEW.receipt,'$.invitation_timing.created_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.invitation_timing.created_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.invitation_timing.created_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) IS NOT (substr(json_extract(NEW.receipt,'$.create.outcome.created_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.create.outcome.created_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.create.outcome.created_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)))
))
BEGIN SELECT RAISE(ABORT,'invitation timing conflict'); END;

